// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.productivity.noteimport androidx.room.Daoimport androidx.room.Deleteimport androidx.room.Insertimport androidx.room.OnConflictStrategyimport androidx.room.Queryimport androidx.room.Update/** * NOUS — Note DAO (Module 14 v1.2 — Step 14.3). * * Production-ready Room DAO for the `notes` table + FTS4 search index. * * ## Search Queries * * All search methods accept a query string that MUST be sanitized via * [com.roshan.persona.productivity.alarm.Fts5Utils] before being passed: * * ```kotlin * val sanitized = Fts5Utils.escapeFts5Query(userQuery) * val results = noteDao.search(sanitized) * * val prefix = Fts5Utils.buildPrefixQuery(userQuery) * val results = noteDao.searchPrefix(prefix) * ``` * * The DAO itself does NOT sanitize — sanitization happens at the * [NoteEngine] layer so the DAO stays a thin data-access interface. * * ## v1 Usage * * This DAO is the production-ready Room contract. In v1, [NoteEngine] * uses the in-memory [NoteStore] (which mirrors this DAO's interface) * for actual persistence. When the production Room DB is wired (post- * Module 12 SqlCipherMigration), [NoteEngine] switches to use this DAO. */@Daointerface NoteDao {    // ═══════════════════════════════════════════════════════════════════════════    // CRUD    // ═══════════════════════════════════════════════════════════════════════════    @Insert(onConflict = OnConflictStrategy.REPLACE)    suspend fun upsert(entity: NoteEntity): Long    @Update    suspend fun update(entity: NoteEntity): Int    @Delete    suspend fun delete(entity: NoteEntity): Int    @Query("DELETE FROM notes WHERE id = :id")    suspend fun deleteById(id: String): Int    @Query("SELECT * FROM notes WHERE id = :id")    suspend fun getById(id: String): NoteEntity?    @Query("SELECT * FROM notes ORDER BY updated_at_ms DESC")    suspend fun getAll(): List<NoteEntity>    @Query("SELECT * FROM notes WHERE tags LIKE '%' || :tag || '%' ORDER BY updated_at_ms DESC")    suspend fun getByTag(tag: String): List<NoteEntity>    @Query("SELECT COUNT(*) FROM notes")    suspend fun count(): Int    // ═══════════════════════════════════════════════════════════════════════════    // FTS4 search (use Fts5Utils.escapeFts5Query before calling)    // ═══════════════════════════════════════════════════════════════════════════    /**     * Full-text search via FTS4 MATCH.     *     * Caller MUST sanitize [query] via     * [com.roshan.persona.productivity.alarm.Fts5Utils.escapeFts5Query]     * before invoking — otherwise FTS5 operators in the user input will     * break the query.     *     * Example:     * ```     * val sanitized = Fts5Utils.escapeFts5Query("meeting notes")     * val results = noteDao.search(sanitized)     * ```     */    @Query(        """        SELECT notes.* FROM notes        JOIN notes_fts ON notes.id = notes_fts.docid        WHERE notes_fts MATCH :query                """,    )    suspend fun search(query: String): List<NoteEntity>    /**     * Prefix search via FTS4 MATCH with trailing asterisk.     *     * Caller MUST build the query via     * [com.roshan.persona.productivity.alarm.Fts5Utils.buildPrefixQuery].     *     * Example:     * ```     * val prefix = Fts5Utils.buildPrefixQuery("med")  // "med*"     * val results = noteDao.searchPrefix(prefix)     * ```     */    @Query(        """        SELECT notes.* FROM notes        JOIN notes_fts ON notes.id = notes_fts.docid        WHERE notes_fts MATCH :query                """,    )    suspend fun searchPrefix(query: String): List<NoteEntity>    /**     * Search with snippet excerpt (for UI display).     *     * Returns the matching note + a short snippet around the match.     * Uses SQLite's `snippet()` function (FTS4 built-in).     */    @Query(        """        SELECT notes.*, snippet(notes_fts, '<b>', '</b>', '...', 1, 32) AS snippet        FROM notes JOIN notes_fts ON notes.id = notes_fts.docid        WHERE notes_fts MATCH :query                LIMIT :limit        """,    )    suspend fun searchWithSnippet(query: String, limit: Int = 20): List<NoteSearchRow>    // ═══════════════════════════════════════════════════════════════════════════    // Bulk operations    // ═══════════════════════════════════════════════════════════════════════════    @Query("DELETE FROM notes")    suspend fun deleteAll(): Int}/** * Row returned by [NoteDao.searchWithSnippet] — note + match snippet. */data class NoteSearchRow(    @androidx.room.ColumnInfo(name = "id") val id: String,    @androidx.room.ColumnInfo(name = "title") val title: String,    @androidx.room.ColumnInfo(name = "body_iv") val bodyIv: String?,    @androidx.room.ColumnInfo(name = "body_ciphertext") val bodyCiphertext: String?,    @androidx.room.ColumnInfo(name = "plain_text_body") val plainTextBody: String,    @androidx.room.ColumnInfo(name = "content_type") val contentType: String,    @androidx.room.ColumnInfo(name = "tags") val tags: String,    @androidx.room.ColumnInfo(name = "created_at_ms") val createdAtMs: Long,    @androidx.room.ColumnInfo(name = "updated_at_ms") val updatedAtMs: Long,    @androidx.room.ColumnInfo(name = "snippet") val snippet: String,)